import { completeJson } from "./llm.js";

// Fixed, server-side wording. It is NOT generated by the model so it can never
// be dropped, softened or contradicted by an AI response.
export const OUTLOOK_DISCLAIMER =
  "This is an estimate, not a prediction. Admissions and hiring decisions depend on factors this tool cannot see " +
  "(applicant pool, test scores, recommendations, interviews, timing, luck). Do not treat any percentage as certain, " +
  "and never make a major decision based on this report alone.";

const OUTLOOK_SCHEMA = {
  name: "admission_outlook",
  schema: {
    type: "object",
    properties: {
      band: { type: "string", enum: ["Long shot", "Reach", "Competitive", "Target", "Strong"] },
      chanceLow: { type: "number", description: "Lower bound of plausible chance, 0-100" },
      chanceHigh: { type: "number", description: "Upper bound of plausible chance, 0-100" },
      confidence: { type: "string", enum: ["low", "medium"] },
      summary: { type: "string" },
      strengths: { type: "array", items: { type: "string" } },
      risks: { type: "array", items: { type: "string" } },
      unknowns: { type: "array", items: { type: "string" } },
      plan: {
        type: "array",
        items: {
          type: "object",
          properties: {
            timeframe: { type: "string" },
            goal: { type: "string" },
            actions: { type: "array", items: { type: "string" } },
          },
          required: ["timeframe", "goal", "actions"],
          additionalProperties: false,
        },
      },
      prepChecklist: { type: "array", items: { type: "string" } },
      interviewPrep: { type: "array", items: { type: "string" } },
    },
    required: [
      "band", "chanceLow", "chanceHigh", "confidence", "summary", "strengths",
      "risks", "unknowns", "plan", "prepChecklist", "interviewPrep",
    ],
    additionalProperties: false,
  },
  strict: true,
};

const clamp = (n, lo, hi) => Math.max(lo, Math.min(hi, Number.isFinite(n) ? n : lo));

/** Never let the output look more certain than it is. */
export function sanitizeOutlook(o) {
  let low = clamp(Math.round(o.chanceLow), 2, 85);
  let high = clamp(Math.round(o.chanceHigh), 2, 90);
  if (high < low) [low, high] = [high, low];
  if (high - low < 15) high = Math.min(90, low + 15); // always a wide range, never a point estimate
  if (high - low < 15) low = Math.max(2, high - 15);
  const cut = (arr, n) => (Array.isArray(arr) ? arr.slice(0, n).map(String) : []);
  return {
    band: o.band,
    chanceLow: low,
    chanceHigh: high,
    confidence: "low" === o.confidence ? "low" : "medium",
    summary: String(o.summary ?? ""),
    strengths: cut(o.strengths, 5),
    risks: cut(o.risks, 5),
    unknowns: cut(o.unknowns, 6),
    plan: (o.plan ?? []).slice(0, 4).map((p) => ({
      timeframe: String(p.timeframe),
      goal: String(p.goal),
      actions: cut(p.actions, 5),
    })),
    prepChecklist: cut(o.prepChecklist, 10),
    interviewPrep: cut(o.interviewPrep, 6),
  };
}

/**
 * Qualitative chance estimate + preparation plan for one target, grounded in the
 * rule-based findings (scores, target fit, background facts) rather than raw text alone.
 */
export async function generateOutlook({ resumeText, analysis, background, targetMatch }) {
  const system = `You are an experienced admissions/hiring advisor inside ResumeIQ.
Estimate how competitive this candidate is for the target and build a preparation plan.

GROUND TRUTH (computed by a deterministic engine; trust it, do not re-derive):
- Target: ${targetMatch.target.label} (${targetMatch.target.type}); rule-based fit ${targetMatch.fitScore}/100
- Overall resume score: ${analysis?.overallScore ?? "n/a"}/100; category scores: ${JSON.stringify(analysis?.categoryScores ?? {})}
- Missing target keywords: ${targetMatch.keywords.missing.join(", ") || "none"}
- Target focus areas: ${targetMatch.focusAreas.join(" | ")}
- Background facts: ${JSON.stringify(background)}
- Warnings: ${(analysis?.warnings ?? []).join(" | ") || "none"}

RULES:
- Output a WIDE plausible range (at least 15 points wide) for chanceLow/chanceHigh, never a single number. Never exceed 90 or go below 2.
- confidence is "low" unless the resume gives rich evidence; you cannot see test scores, recommendations, essays, the applicant pool, or the interview.
- Selective programs/companies have low base rates even for strong candidates; reflect that honestly.
- Use only facts present above or in the resume text. List what you cannot see under "unknowns" (e.g. GPA, test scores, recommendation letters, visa/work authorization).
- plan: 3-4 phases with concrete, resume-specific actions (timeframes like "Next 2 weeks", "1-3 months", "3-6 months").
- prepChecklist: documents and materials to prepare for this specific target (e.g. SOP, recommendation letters, portfolio, transcripts, referral outreach).
- interviewPrep: 4-6 likely questions tied to the candidate's actual experience.
- Be candid but encouraging; no guarantees, no flattery.`;

  const raw = await completeJson({
    system,
    user: resumeText.slice(0, 6000),
    schema: OUTLOOK_SCHEMA,
    temperature: 0.4,
  });
  return sanitizeOutlook(raw);
}
